        for k in range(i + 1, n):
            if abs(matrix[k][i]) > abs(matrix[max_row][i]):
                max_row = k
        matrix[i], matrix[max_row] = matrix[max_row], matrix[i]

        # Eliminate below
        factor = Fraction(-matrix[i][i], matrix[i][i])
        for j in range(i, n):
            matrix[i][j] *= factor
        for k in range(n):
            if k != i:
                factor = matrix[k][i]
                for j in range(i, n):
                    matrix[k][j] += factor * matrix[i][j]

    rank = 0
    for row in matrix:
